/**
 * @file tss_app.h
 * @brief Glue between the fan-anomaly application and the Time Series Studio run-time.
 *
 * TimeSeries.h is regenerated by Time Series Studio on every export, and its shape
 * depends on the tool version: the current header no longer publishes macros such as
 * TSS_INPUT_DATA_LEN / MODEL_SIZE, but a task-ops table returned by ::tss_get_task_ops()
 * plus a ::tss_algo_attribute_t descriptor.
 *
 * This module is the only place in the application that has to know that layout. It
 * resolves the ops table once, validates that the exported model matches the input
 * window the acquisition pipeline is built around (::APP_TSS_WINDOW_LEN samples of
 * ::APP_TSS_WINDOW_DIM channels) and exposes a small, stable accessor set.
 */

#ifndef TSS_APP_H_
#define TSS_APP_H_

#include <stdint.h>

#include "TimeSeries.h"

/*******************************************************************************
 * Definitions
 ******************************************************************************/
/*! @brief Samples per model input window (the TSS "window size"). */
#define APP_TSS_WINDOW_LEN (128U)

/*! @brief Channels per sample (X/Y/Z acceleration). */
#define APP_TSS_WINDOW_DIM (3U)

/*! @brief Floats in one model input window. */
#define APP_TSS_WINDOW_FLOATS (APP_TSS_WINDOW_LEN * APP_TSS_WINDOW_DIM)

/*! @brief Capacity, in floats, of the model record kept in flash.
 *
 *  Only a bound: the actually used length is ::tss_algo_attribute_t::model_size and is
 *  checked against it by ::APP_TSS_Init(). */
#define APP_TSS_MODEL_MAX_FLOATS (256U)

/*******************************************************************************
 * API
 ******************************************************************************/
/*! @brief       Resolve and validate the TSS task-ops table.
 *  @details     Idempotent. Verifies that the linked library implements anomaly
 *               detection with on-device learning (::TASK_AD_ODL), that its model
 *               window is ::APP_TSS_WINDOW_LEN x ::APP_TSS_WINDOW_DIM and that the
 *               exported weights fit in ::APP_TSS_MODEL_MAX_FLOATS. Every failure is
 *               reported on the console.
 *  @return      The model attributes on success, NULL if the application and the
 *               linked TSS library do not agree.
 */
const tss_algo_attribute_t *APP_TSS_Init(void);

/*! @brief       Attributes of the linked model, or NULL before ::APP_TSS_Init(). */
const tss_algo_attribute_t *APP_TSS_Attribute(void);

/*! @brief       Anomaly-detection-with-ODL entry points, or NULL before ::APP_TSS_Init(). */
const tss_ad_odl_task_ops_t *APP_TSS_Ops(void);

#endif /* TSS_APP_H_ */
